<script setup lang="ts">
import {ref,reactive,computed,watch,onMounted,onBeforeUnmount} from 'vue';import {api} from '../api';import {campaignApi} from '../campaign-api';import {campaignDates,autoCampaignSchedule} from '../campaign-scheduling';import {useWorkspace,type WorkTab} from '../stores';
import CampaignPreviewTable from '../components/CampaignPreviewTable.vue';
const workspace=useWorkspace();
import Modal from '../components/Modal.vue';import CampaignRecords from '../components/CampaignRecords.vue';import CampaignDepartment from '../components/CampaignDepartment.vue';import CampaignStoreEditor from '../components/CampaignStoreEditor.vue';import ActivityPlan from '../components/ActivityPlan.vue';
const props=defineProps<{tab:WorkTab}>();const loading=ref(true),error=ref(''),message=ref(''),campaign=ref<any>(null),stores=ref<any[]>([]),rows=ref<any[]>([]),settings=ref<any[]>([]),events=ref<any[]>([]),permissions=ref<any>({}),marketing=ref(false),merchandise=ref(false),version=ref(''),baseline=ref('[]'),requestId=ref(crypto.randomUUID()),active=ref('schedule'),visited=reactive(new Set(['schedule'])),revision=ref(0),selected=ref(''),date=ref(''),storeDialog=ref<any>(null),initial=ref('details'),discardStore=ref(false),confirmation=ref(''),autoResult=ref<any>(null),publishTarget=ref(''),working=ref(false),plan=ref<any>(null),planLoading=ref(false),planError=ref('');
const detailIds=ref<string[]>([]),detailError=ref('');
async function refreshDetails(){try{detailIds.value=((await campaignApi('details',{campaign_id:props.tab.recordId!})).data||[]).map((r:any)=>r.store_id);detailError.value='';}catch(e){detailError.value=(e as Error).message;}}
const sections=[['schedule','活動排程'],['stores','門市細節／人力'],['preview','規劃預覽'],['trips','設備車次'],['checklist','工作清單'],['marketing','行銷部'],['merchandise','商品部']];
const children=reactive(Object.fromEntries(['store','trips','checklist','marketing','merchandise'].map(k=>[k,{...props.tab,id:props.tab.id+'-'+k,dirty:false,busy:false,save:undefined,discard:undefined}])) as Record<string,WorkTab>);
const normalized=()=>rows.value.map(r=>({store_id:r.store_id,activity_date:r.activity_date})).sort((a,b)=>a.store_id.localeCompare(b.store_id));
const dirty=computed(()=>JSON.stringify(normalized())!==baseline.value);watch(rows,()=>requestId.value=crypto.randomUUID(),{deep:true,flush:'sync'});
watch(()=>[dirty.value,working.value,...Object.values(children).flatMap(t=>[t.dirty,t.busy])],()=>{props.tab.dirty=dirty.value||Object.values(children).some(t=>t.dirty);props.tab.busy=working.value||Object.values(children).some(t=>t.busy);},{flush:'sync'});props.tab.submitOnly=true;
const dates=computed(()=>campaign.value?campaignDates(campaign.value.start_date,campaign.value.end_date):[]),months=computed(()=>Array.from(new Set(dates.value.map(d=>d.slice(0,7)))).map(month=>({month,dates:dates.value.filter(d=>d.startsWith(month))})));
const unscheduled=computed(()=>stores.value.filter(s=>!rows.value.some(r=>r.store_id===s.id)));const storeName=(id:string)=>{const s=stores.value.find(s=>s.id===id);return s?s.store_code+' '+s.store_name:id;};
async function load(){loading.value=true;error.value='';try{const [c,s,t,e,p,r]=await Promise.all([api('campaigns?id='+props.tab.recordId),campaignApi('stores'),campaignApi('settings'),campaignApi('events'),campaignApi('permissions'),campaignApi('schedules',{campaign_id:props.tab.recordId!})]);campaign.value=c.records[0];if(!campaign.value)throw Error('活動已不存在');stores.value=s.stores||s.data||[];settings.value=t.settings||[];events.value=e.events||[];permissions.value=p.permissions;marketing.value=p.marketing;merchandise.value=p.merchandise;rows.value=r.schedules||[];version.value=r.version;baseline.value=JSON.stringify(normalized());props.tab.title='活動規劃 · '+campaign.value.name;date.value=campaign.value.start_date;for(const t of Object.values(children)){t.dirty=false;t.busy=false;}revision.value++;await refreshDetails();}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
function select(key:string){if(props.tab.busy)return;active.value=key;visited.add(key);if(key==='preview')void loadPlan();}
function assign(id:string,d:string){if(!permissions.value.schedules||props.tab.busy)return;if(!stores.value.some(s=>s.id===id)||!dates.value.includes(d)){error.value='請選擇活動期間內的日期與有效門市';return;}rows.value=rows.value.filter(r=>r.store_id!==id).concat({store_id:id,activity_date:d});message.value='已更新排程草稿，請儲存變更。';}
function drop(event:DragEvent,d:string){event.preventDefault();const id=event.dataTransfer?.getData('storeId');if(id)assign(id,d);}
async function save(){working.value=true;error.value='';try{const r=await campaignApi('schedules',{},'PUT',{campaign_id:props.tab.recordId,rows:normalized(),version:version.value,requestId:requestId.value});version.value=r.version;baseline.value=JSON.stringify(normalized());message.value='已儲存所有排程變更';confirmation.value='';}catch(e){error.value=(e as Error).message;}finally{working.value=false;}}
function openStore(s:any,section='details'){initial.value=section;children.store.dirty=false;storeDialog.value=s;}
function closeStore(){if(props.tab.busy)return;if(children.store.dirty)discardStore.value=true;else{storeDialog.value=null;void refreshDetails();}}
async function publish(){working.value=true;error.value='';try{const kind=publishTarget.value;const r=await campaignApi('publish',{},'PATCH',{campaignId:campaign.value.id,publishType:kind,status:!campaign.value['published_to_'+kind]});campaign.value=r.campaign;publishTarget.value='';message.value='已更新活動發布對象';const schedules=await campaignApi('schedules',{campaign_id:campaign.value.id});version.value=schedules.version;}catch(e){error.value=(e as Error).message;}finally{working.value=false;}}
async function loadPlan(){planLoading.value=true;planError.value='';const keys=['details','ownStaff','requests','supportStaff','headcount','checklist','completions','trips','departments'];try{const responses=await Promise.allSettled(keys.map(k=>campaignApi(k,{campaign_id:campaign.value.id})));const result:any={errors:{}};responses.forEach((r,i)=>{if(r.status==='fulfilled')result[keys[i]]=r.value.data;else{result[keys[i]]=keys[i]==='departments'?null:[];result.errors[keys[i]]=(r.reason as Error).message;}});const schedules=(await campaignApi('schedules',{campaign_id:campaign.value.id})).schedules;plan.value={campaign:campaign.value,schedules,plan:result};}catch(e){planError.value=(e as Error).message;}finally{planLoading.value=false;}}
onMounted(load);onBeforeUnmount(()=>{delete props.tab.submitOnly;});
</script>
<template><header class="page-heading"><div><p class="eyebrow">活動管理 / 活動規劃</p><h1>{{campaign?.name||'活動規劃'}}</h1><p v-if="campaign">{{campaign.start_date}} — {{campaign.end_date}} · {{campaign.campaign_type==='inventory'?'盤點活動':'促銷活動'}}</p></div><button :disabled="loading||tab.busy" @click="tab.dirty?confirmation='reload':load()">重新整理</button></header>
<p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><p v-if="loading">正在讀取活動規劃…</p><template v-else-if="campaign">
<div v-if="permissions.publish" class="publish"><button v-for="[key,label] in [['supervisors','督導'],['store_managers','店長'],['inventory_team','盤點組人員']]" :disabled="tab.busy||tab.dirty" @click="publishTarget=key">{{campaign['published_to_'+key]?'取消發布給':'發布給'}}{{label}}</button><span v-if="tab.dirty">請先儲存各區修改，再發布。</span></div>
<nav class="sections" aria-label="活動規劃分區"><button v-for="[key,label] in sections" :aria-pressed="active===key" :disabled="tab.busy" @click="select(key)">{{label}}<span v-if="children[key]?.dirty"> · 未儲存</span></button></nav>
<section v-show="active==='schedule'"><div v-if="permissions.schedules" class="toolbar"><button :disabled="tab.busy" @click="autoResult=autoCampaignSchedule(stores,dates,settings,events)">自動排程</button><button class="primary" :disabled="!dirty||tab.busy" @click="confirmation='save'">儲存所有排程變更</button><button :disabled="!dirty||tab.busy" @click="confirmation='cancel'">取消排程變更</button></div>
<form v-if="permissions.schedules" class="filters" @submit.prevent="assign(selected,date)"><label>安排門市<select aria-label="安排門市" v-model="selected" required><option value="">選擇門市</option><option v-for="s in stores" :value="s.id">{{s.store_code}} {{s.store_name}}</option></select></label><label>活動日期<input type="date" v-model="date" :min="campaign.start_date" :max="campaign.end_date" required></label><button :disabled="tab.busy">安排／移動門市</button></form>
<h2>尚未安排（{{unscheduled.length}}）</h2><div class="unscheduled"><button v-for="s in unscheduled" :draggable="!!permissions.schedules" @dragstart="e=>e.dataTransfer?.setData('storeId',s.id)" @click="selected=s.id" :disabled="!permissions.schedules">{{s.store_code}} {{s.store_name}}</button><span v-if="!unscheduled.length">全部門市皆已安排。</span></div>
<p>可拖曳門市至日期，或使用上方門市與日期選單安排。特殊日期限制用於自動排程，手動安排可另行調整。</p>
<div v-for="m in months" :key="m.month" class="month"><h2>{{m.month}}</h2><div class="calendar"><div v-for="day in ['日','一','二','三','四','五','六']" class="weekday">{{day}}</div><div v-for="i in new Date(m.dates[0]+'T00:00:00Z').getUTCDay()" class="blank"/><div v-for="d in m.dates" :key="d" class="day" @dragover.prevent @drop="drop($event,d)"><strong>{{d.slice(8)}}<span class="mobile-date">（{{['日','一','二','三','四','五','六'][new Date(d+'T00:00:00Z').getUTCDay()]}}）</span></strong><small v-for="e in events.filter(e=>e.event_date.slice(0,10)===d)">{{e.description}} {{e.is_blocked?'／禁止自動排程':''}}</small><div v-for="r in rows.filter(r=>r.activity_date===d)" :key="r.store_id" class="scheduled" :draggable="!!permissions.schedules" @dragstart="e=>e.dataTransfer?.setData('storeId',r.store_id)"><span>{{storeName(r.store_id)}}</span><button v-if="permissions.schedules" :disabled="tab.busy" :aria-label="'移除 '+storeName(r.store_id)+' 排程'" @click="rows=rows.filter(x=>x.store_id!==r.store_id)">移除</button></div></div></div></div></section>
<section v-show="active==='stores'"><h2>門市規劃與人力安排</h2><div class="module-table"><table><thead><tr><th>門市</th><th>督導</th><th>活動日期</th><th>細節狀態</th><th>操作</th></tr></thead><tbody><tr v-for="s in stores" :key="s.id"><td>{{s.store_code}} {{s.store_name}}</td><td>{{s.supervisor_name||'未指派'}}</td><td>{{rows.find(r=>r.store_id===s.id)?.activity_date||'尚未安排'}}</td><td>{{detailError?'狀態讀取失敗':detailIds.includes(s.id)?'已設定':'待填寫'}}</td><td><button @click="openStore(s)">門市細節／工作回報</button><button @click="openStore(s,'people')">本店與支援人力</button></td></tr></tbody></table></div></section>
<section v-show="active==='preview'"><p v-if="dirty" class="notice">以下預覽為已儲存的排程與規劃。</p><p v-if="planLoading">正在讀取規劃結果…</p><p v-if="planError" role="alert">{{planError}} <button @click="loadPlan">重試</button></p><CampaignPreviewTable v-if="plan&&!planLoading" :data="plan" :active="active==='preview'&&workspace.active===tab.id"/><ActivityPlan back-label="返回門市規劃" v-if="plan&&!planLoading" :data="plan" :store="tab.store" @back="select('stores')" @retry="loadPlan"/></section>
<template v-for="kind in ['trips','checklist'] as const"><section v-if="visited.has(kind)" v-show="active===kind"><CampaignRecords :key="kind+'-'+revision" :kind="kind" :campaign="campaign" :stores="stores" :can-edit="!!permissions[kind]" :tab="children[kind]"/></section></template>
<template v-for="department in ['marketing','merchandise'] as const"><section v-if="visited.has(department)" v-show="active===department"><CampaignDepartment :key="department+'-'+revision" :department="department" :campaign="campaign" :can-edit="department==='marketing'?marketing:merchandise" :tab="children[department]"/></section></template>
</template>
<Modal v-if="storeDialog" :title="storeName(storeDialog.id)+' · 活動規劃'" wide :busy="tab.busy" @cancel="closeStore"><CampaignStoreEditor :campaign="campaign" :store="storeDialog" :stores="stores" :permissions="permissions" :tab="children.store" :initial="initial"/><div class="dialog-actions"><button :disabled="tab.busy" @click="closeStore">關閉門市規劃</button></div></Modal>
<Modal v-if="discardStore" title="放棄門市規劃修改？" @cancel="discardStore=false"><p>此門市尚未儲存的配置或人力草稿將被放棄。</p><div class="dialog-actions"><button @click="discardStore=false">繼續編輯</button><button class="danger" @click="storeDialog=null;discardStore=false;children.store.dirty=false">放棄修改</button></div></Modal>
<Modal v-if="confirmation" :title="confirmation==='save'?'儲存所有排程變更？':'放棄未儲存的修改？'" :busy="tab.busy" @cancel="confirmation=''"><p>{{confirmation==='save'?'將儲存 '+rows.length+' 間門市排程，移除的排程也會生效。':confirmation==='cancel'?'將恢復原本已儲存的排程。':'各區未儲存內容將被放棄並重新讀取。'}}</p><p v-if="error" role="alert">{{error}}</p><div class="dialog-actions"><button :disabled="tab.busy" @click="confirmation=''">返回</button><button :disabled="tab.busy" class="primary" @click="confirmation==='save'?save():confirmation==='cancel'?(rows=JSON.parse(baseline),confirmation=''):(confirmation='',load())">確認</button></div></Modal>
<Modal v-if="autoResult" title="套用自動排程？" @cancel="autoResult=null"><p>依週三、週六、週日、門市星期限制、特殊日期及督導區安排；同督導區優先避免相鄰日期，無法安排時放寬相鄰限制。</p><p>可安排 {{autoResult.schedules.length}}／{{stores.length}} 間，將取代目前排程草稿，仍須儲存才會生效。</p><ul v-if="autoResult.failed.length"><li v-for="s in autoResult.failed">{{s.store_name}}：無符合限制的日期，請手動安排或調整設定。</li></ul><div class="dialog-actions"><button @click="autoResult=null">保留目前排程</button><button class="primary" @click="rows=autoResult.schedules;autoResult=null">套用至草稿</button></div></Modal>
<Modal v-if="publishTarget" title="更新活動發布對象？" :busy="tab.busy" @cancel="publishTarget=''"><p>{{campaign['published_to_'+publishTarget]?'取消發布後該對象將無法由活動檢視查看。':'發布後該對象可在活動檢視查看已儲存的規劃。'}}</p><p v-if="error" role="alert">{{error}}</p><div class="dialog-actions"><button :disabled="tab.busy" @click="publishTarget=''">取消</button><button class="primary" :disabled="tab.busy" @click="publish">確認更新</button></div></Modal>
</template>
<style scoped>.sections,.publish,.toolbar,.filters,.unscheduled{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0}.sections{border-bottom:1px solid var(--line);padding-bottom:14px}.sections [aria-pressed=true]{background:var(--primary);color:white}.filters{align-items:end}.filters label{display:grid;gap:8px}h2{font-size:18px;margin:24px 0 12px}.calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px}.weekday{text-align:center;padding:8px}.day{border:1px solid var(--line);padding:10px;min-height:120px;background:var(--surface)}.day small{display:block;color:var(--muted);margin:6px 0}.scheduled{border-left:3px solid var(--primary);padding:6px;margin:8px 0;background:var(--bg)}.scheduled span{display:block;overflow-wrap:anywhere}.scheduled button{padding:3px 6px;min-height:28px;font-size:12px}.mobile-date{display:none}td button{margin:4px}section{min-width:0}@media(max-width:800px){.calendar{grid-template-columns:1fr 1fr}.weekday,.blank{display:none}.mobile-date{display:inline}.filters{display:grid;grid-template-columns:1fr}.filters input,.filters select{width:100%}}@media(max-width:450px){.calendar{grid-template-columns:1fr}}
</style>
